     "t": "code",
     "lang": "text",
     "code": "Q155: Composition\n  Toyota Camry is driving\n  Engine running: True\n  Current gear: 1\n  Toyota Camry is parked\n\n  Swapped engine: Toyota Camry is driving",
     "numbered": false
