     "t": "code",
     "lang": "text",
     "code": "Q157: Method Overriding\n  Payment: Processing $100 payment\n  CreditCardPayment: Charging $100 to credit card\n  PayPalPayment: PayPal: Processing $100 payment (with PayPal fees)",
