     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nCLASS METHODS\n==============\n\n@classmethod: a method that receives the CLASS (cls) as first argument\ninstead of the instance (self).\n\nUse cases:\n  - Alternative constructors (factory methods)\n  - Modifying class state\n  - Accessing class variables\n  - Creating instances in a flexible way\n\"\"\"\n\n\nclass Date:\n    def __init__(self, year, month, day):\n        self.year = year\n        self.month = month\n        self.day = day\n\n    @classmethod\n    def from_string(cls, date_string):\n        \"\"\"Alternative constructor from string.\"\"\"\n        year, month, day = map(int, date_string.split(\"-\"))\n        return cls(year, month, day)  # Uses cls, not Date — works with subclasses!\n\n    @classmethod\n    def today(cls):\n        \"\"\"Alternative constructor for today's date.\"\"\"\n        import datetime\n        d = datetime.date.today()\n        return cls(d.year, d.month, d.day)\n\n    def __repr__(self):\n        return f\"{self.__class__.__name__}({self.year}-{self.month:02d}-{self.day:02d})\"\n\n\nclass DateTime(Date):\n    \"\"\"Subclass — classmethod returns DateTime, not Date!\"\"\"\n    pass\n\n\ndef demo_class_methods():\n    d1 = Date(2024, 1, 15)\n    d2 = Date.from_string(\"2024-06-20\")\n    d3 = Date.today()\n\n    print(f\"  d1: {d1}\")\n    print(f\"  d2: {d2}\")\n    print(f\"  d3: {d3}\")\n\n    # Subclass gets correct type\n    dt = DateTime.from_string(\"2024-12-25\")\n    print(f\"  dt: {dt} (type: {type(dt).__name__})\")  # DateTime, not Date!\n\n\nprint(\"Q165: Class Methods\")\ndemo_class_methods()\nprint()",
