     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nMIXINS\n=======\n\nA mixin is a class that provides methods to other classes through\nmultiple inheritance, but is not meant to stand alone.\n\nCharacteristics:\n  - Single responsibility (one feature)\n  - No __init__ (or very minimal)\n  - Doesn't store instance state (usually)\n  - Named with \"Mixin\" suffix (convention)\n  - Designed to be combined via multiple inheritance\n\"\"\"\n\n\nclass JsonMixin:\n    \"\"\"Mixin to add JSON serialization.\"\"\"\n    def to_json(self):\n        import json\n        return json.dumps(self.__dict__, default=str)\n\n    @classmethod\n    def from_json(cls, json_str):\n        import json\n        data = json.loads(json_str)\n        obj = cls.__new__(cls)\n        obj.__dict__.update(data)\n        return obj\n\n\nclass LogMixin:\n    \"\"\"Mixin to add logging capability.\"\"\"\n    def log(self, message):\n        print(f\"  [{self.__class__.__name__}] {message}\")\n\n\nclass TimestampMixin:\n    \"\"\"Mixin to add timestamp.\"\"\"\n    def get_timestamp(self):\n        from datetime import datetime\n        return datetime.now().isoformat()\n\n\nclass User(JsonMixin, LogMixin, TimestampMixin):\n    def __init__(self, name, email):\n        self.name = name\n        self.email = email\n\n\ndef demo_mixins():\n    user = User(\"Alice\", \"alice@example.com\")\n    print(f\"  JSON: {user.to_json()}\")\n    user.log(\"User created\")\n    print(f\"  Timestamp: {user.get_timestamp()}\")\n    print(f\"  MRO: {[c.__name__ for c in User.__mro__]}\")\n\n\nprint(\"Q168: Mixins\")\ndemo_mixins()\nprint()",
