     "code": "\"\"\"\nFACTORY PATTERN\n================\n\nCreates objects without exposing creation logic.\nClient doesn't need to know which concrete class to instantiate.\n\"\"\"\n\n\nclass Notification(ABC):\n    @abstractmethod\n    def send(self, message):\n        pass\n\n\nclass EmailNotification(Notification):\n    def send(self, message):\n        return f\"Email: {message}\"\n\n\nclass SMSNotification(Notification):\n    def send(self, message):\n        return f\"SMS: {message}\"\n\n\nclass PushNotification(Notification):\n    def send(self, message):\n        return f\"Push: {message}\"\n\n\nclass NotificationFactory:\n    \"\"\"Factory that creates the right notification type.\"\"\"\n    _creators = {\n        \"email\": EmailNotification,\n        \"sms\": SMSNotification,\n        \"push\": PushNotification,\n    }\n\n    @classmethod\n    def create(cls, notification_type: str) -> Notification:\n        creator = cls._creators.get(notification_type)\n        if not creator:\n            raise ValueError(f\"Unknown type: {notification_type}\")\n        return creator()\n\n    @classmethod\n    def register(cls, name: str, creator):\n        \"\"\"Allow extending with new types.\"\"\"\n        cls._creators[name] = creator\n\n\ndef demo_factory():\n    for ntype in [\"email\", \"sms\", \"push\"]:\n        notif = NotificationFactory.create(ntype)\n        print(f\"  {notif.send('Hello!')}\")\n\n\nprint(\"Q170: Factory Pattern\")\ndemo_factory()\nprint()",
     "numbered": false
