     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nABSTRACT FACTORY PATTERN\n==========================\n\nProvides an interface for creating FAMILIES of related objects\nwithout specifying concrete classes.\n\"\"\"\n\n\nclass Button(ABC):\n    @abstractmethod\n    def render(self): pass\n\n\nclass TextBox(ABC):\n    @abstractmethod\n    def render(self): pass\n\n\nclass WindowsButton(Button):\n    def render(self): return \"[Windows Button]\"\n\n\nclass WindowsTextBox(TextBox):\n    def render(self): return \"[Windows TextBox]\"\n\n\nclass MacButton(Button):\n    def render(self): return \"(Mac Button)\"\n\n\nclass MacTextBox(TextBox):\n    def render(self): return \"(Mac TextBox)\"\n\n\nclass GUIFactory(ABC):\n    @abstractmethod\n    def create_button(self) -> Button: pass\n\n    @abstractmethod\n    def create_textbox(self) -> TextBox: pass\n\n\nclass WindowsFactory(GUIFactory):\n    def create_button(self): return WindowsButton()\n    def create_textbox(self): return WindowsTextBox()\n\n\nclass MacFactory(GUIFactory):\n    def create_button(self): return MacButton()\n    def create_textbox(self): return MacTextBox()\n\n\ndef demo_abstract_factory():\n    for factory in [WindowsFactory(), MacFactory()]:\n        button = factory.create_button()\n        textbox = factory.create_textbox()\n        print(f\"  {type(factory).__name__}: {button.render()} {textbox.render()}\")\n\n\nprint(\"Q171: Abstract Factory Pattern\")\ndemo_abstract_factory()\nprint()",
