     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nBUILDER PATTERN\n================\n\nConstructs complex objects step by step.\nSeparates construction from representation.\nUseful when object has many optional parameters.\n\"\"\"\n\n\nclass QueryBuilder:\n    \"\"\"SQL query builder.\"\"\"\n\n    def __init__(self):\n        self._table = None\n        self._columns = [\"*\"]\n        self._conditions = []\n        self._order_by = None\n        self._limit = None\n\n    def table(self, name):\n        self._table = name\n        return self  # Return self for chaining\n\n    def select(self, *columns):\n        self._columns = list(columns)\n        return self\n\n    def where(self, condition):\n        self._conditions.append(condition)\n        return self\n\n    def order(self, column, direction=\"ASC\"):\n        self._order_by = f\"{column} {direction}\"\n        return self\n\n    def limit(self, n):\n        self._limit = n\n        return self\n\n    def build(self):\n        if not self._table:\n            raise ValueError(\"Table name required\")\n\n        query = f\"SELECT {', '.join(self._columns)} FROM {self._table}\"\n        if self._conditions:\n            query += \" WHERE \" + \" AND \".join(self._conditions)\n        if self._order_by:\n            query += f\" ORDER BY {self._order_by}\"\n        if self._limit:\n            query += f\" LIMIT {self._limit}\"\n        return query\n\n\ndef demo_builder():\n    query = (QueryBuilder()\n             .table(\"users\")\n             .select(\"name\", \"email\")\n             .where(\"age > 18\")\n             .where(\"active = 1\")\n             .order(\"name\")\n             .limit(10)\n             .build())\n    print(f\"  {query}\")\n\n\nprint(\"Q172: Builder Pattern\")\ndemo_builder()\nprint()",
