     "code": "class QueryBuilder:\n    def __init__(self):\n        self._select = [\"*\"]\n        self._from = \"\"\n        self._where = []\n        self._order_by = None\n        self._limit = None\n        self._joins = []\n    \n    def select(self, *fields):\n        self._select = list(fields)\n        return self\n    \n    def from_table(self, table):\n        self._from = table\n        return self\n    \n    def where(self, condition):\n        self._where.append(condition)\n        return self\n    \n    def join(self, table, on):\n        self._joins.append(f\"JOIN {table} ON {on}\")\n        return self\n    \n    def order_by(self, field, desc=False):\n        self._order_by = f\"{field} {'DESC' if desc else 'ASC'}\"\n        return self\n    \n    def limit(self, n):\n        self._limit = n\n        return self\n    \n    def build(self):\n        parts = [f\"SELECT {', '.join(self._select)}\"]\n        parts.append(f\"FROM {self._from}\")\n        parts.extend(self._joins)\n        if self._where:\n            parts.append(f\"WHERE {' AND '.join(self._where)}\")\n        if self._order_by:\n            parts.append(f\"ORDER BY {self._order_by}\")\n        if self._limit:\n            parts.append(f\"LIMIT {self._limit}\")\n        return \" \".join(parts)\n\nquery = (QueryBuilder()\n    .select(\"u.name\", \"u.email\", \"o.total\")\n    .from_table(\"users u\")\n    .join(\"orders o\", \"u.id = o.user_id\")\n    .where(\"u.active = 1\")\n    .where(\"o.total > 100\")\n    .order_by(\"o.total\", desc=True)\n    .limit(10)\n    .build())\nprint(query)",
