     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nADAPTER PATTERN\n================\n\nConverts the interface of a class into another interface that clients expect.\nAllows classes with incompatible interfaces to work together.\n\"\"\"\n\n\nclass OldPrinter:\n    \"\"\"Legacy class with old interface.\"\"\"\n    def print_old(self, text):\n        return f\"[OLD PRINTER] {text}\"\n\n\nclass NewPrinter:\n    \"\"\"New class with different interface.\"\"\"\n    def render(self, content):\n        return f\"[NEW PRINTER] {content}\"\n\n\nclass PrinterAdapter:\n    \"\"\"Adapter: makes OldPrinter compatible with NewPrinter interface.\"\"\"\n\n    def __init__(self, old_printer):\n        self.old_printer = old_printer\n\n    def render(self, content):\n        \"\"\"Adapt old interface to new one.\"\"\"\n        return self.old_printer.print_old(content)\n\n\ndef demo_adapter():\n    old = OldPrinter()\n    new = NewPrinter()\n    adapted = PrinterAdapter(old)\n\n    # Both work with the same interface now\n    printers = [new, adapted]\n    for printer in printers:\n        print(f\"  {printer.render('Hello World')}\")\n\n\nprint(\"Q174: Adapter Pattern\")\ndemo_adapter()\nprint()",
