     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nFACADE PATTERN\n===============\n\nProvides a simplified interface to a complex subsystem.\nHides the complexity behind a single, easy-to-use class.\n\"\"\"\n\n\nclass CPU:\n    def freeze(self): return \"CPU frozen\"\n    def jump(self, addr): return f\"CPU jumped to {addr}\"\n    def execute(self): return \"CPU executing\"\n\n\nclass Memory:\n    def load(self, addr, data): return f\"Memory loaded '{data}' at {addr}\"\n\n\nclass HardDrive:\n    def read(self, sector, size): return f\"HardDrive read {size}B from sector {sector}\"\n\n\nclass ComputerFacade:\n    \"\"\"Facade: simplifies computer boot process.\"\"\"\n\n    def __init__(self):\n        self.cpu = CPU()\n        self.memory = Memory()\n        self.hard_drive = HardDrive()\n\n    def start(self):\n        \"\"\"Simple interface to complex boot sequence.\"\"\"\n        steps = [\n            self.cpu.freeze(),\n            self.hard_drive.read(0, 1024),\n            self.memory.load(0, \"boot data\"),\n            self.cpu.jump(0),\n            self.cpu.execute()\n        ]\n        return steps\n\n\ndef demo_facade():\n    computer = ComputerFacade()\n    steps = computer.start()\n    for step in steps:\n        print(f\"  {step}\")\n\n\nprint(\"Q175: Facade Pattern\")\ndemo_facade()\nprint()",
     "numbered": false
