     "code": "class Inventory:\n    def reserve(self, sku, qty):\n        return f\"reserved {qty} x {sku}\"\n\nclass Payments:\n    def charge(self, card, amount):\n        return f\"charged {amount} to {card}\"\n\nclass Shipping:\n    def dispatch(self, sku, address):\n        return f\"dispatched {sku} to {address}\"\n\nclass OrderFacade:\n    \"\"\"One method the caller understands, three subsystems it does not.\"\"\"\n    def __init__(self):\n        self._inventory = Inventory()\n        self._payments = Payments()\n        self._shipping = Shipping()\n\n    def place_order(self, sku, qty, card, address):\n        steps = [self._inventory.reserve(sku, qty),\n                 self._payments.charge(card, qty * 10),\n                 self._shipping.dispatch(sku, address)]\n        return steps\n\nfor line in OrderFacade().place_order(\"BOOK-1\", 2, \"visa\", \"London\"):\n    print(line)\n# Output: reserved 2 x BOOK-1\n# Output: charged 20 to visa\n# Output: dispatched BOOK-1 to London\n\n# The facade does not hide the subsystems - a caller who needs Payments directly\n# can still have it. It just means the common path is one call, not three.",
