     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nOBSERVER PATTERN\n==================\n\nDefines a one-to-many relationship: when the subject changes state,\nall registered observers are notified automatically.\n\nAlso known as: Publish-Subscribe, Event-Listener\n\"\"\"\n\n\nclass EventEmitter:\n    \"\"\"Subject / Observable.\"\"\"\n\n    def __init__(self):\n        self._listeners = {}\n\n    def on(self, event, callback):\n        \"\"\"Register a listener.\"\"\"\n        self._listeners.setdefault(event, []).append(callback)\n\n    def off(self, event, callback):\n        \"\"\"Unregister a listener.\"\"\"\n        if event in self._listeners:\n            self._listeners[event].remove(callback)\n\n    def emit(self, event, *args, **kwargs):\n        \"\"\"Notify all listeners.\"\"\"\n        for callback in self._listeners.get(event, []):\n            callback(*args, **kwargs)\n\n\ndef demo_observer():\n    emitter = EventEmitter()\n\n    # Observers\n    def log_handler(data):\n        print(f\"  Logger: received '{data}'\")\n\n    def email_handler(data):\n        print(f\"  Email: sending notification about '{data}'\")\n\n    def audit_handler(data):\n        print(f\"  Audit: recording '{data}'\")\n\n    emitter.on(\"user_created\", log_handler)\n    emitter.on(\"user_created\", email_handler)\n    emitter.on(\"user_created\", audit_handler)\n\n    print(\"  Emitting 'user_created' event:\")\n    emitter.emit(\"user_created\", \"Alice joined\")\n\n\nprint(\"Q178: Observer Pattern\")\ndemo_observer()\nprint()",
