     "t": "code",
     "lang": "python",
     "code": "\"\"\"\nPROXY PATTERN\n==============\n\nProvides a surrogate or placeholder for another object to control access.\n\nTypes:\n  - Virtual Proxy: lazy initialization\n  - Protection Proxy: access control\n  - Logging Proxy: logging and monitoring\n  - Caching Proxy: cache results\n\"\"\"\n\n\nclass ExpensiveResource:\n    def __init__(self):\n        import time\n        # Simulate expensive initialization\n        self.data = \"expensive data loaded\"\n\n    def process(self):\n        return f\"Processing: {self.data}\"\n\n\nclass LazyProxy:\n    \"\"\"Virtual proxy: delays creation until first use.\"\"\"\n\n    def __init__(self):\n        self._resource = None\n\n    def _ensure_loaded(self):\n        if self._resource is None:\n            print(\"  [Proxy] Loading resource for first time...\")\n            self._resource = ExpensiveResource()\n\n    def process(self):\n        self._ensure_loaded()\n        return self._resource.process()\n\n\nclass ProtectionProxy:\n    \"\"\"Protection proxy: controls access based on role.\"\"\"\n\n    def __init__(self, resource, user_role):\n        self._resource = resource\n        self._user_role = user_role\n\n    def process(self):\n        if self._user_role != \"admin\":\n            return \"Access denied: admin role required\"\n        return self._resource.process()\n\n\ndef demo_proxy():\n    # Lazy proxy\n    proxy = LazyProxy()\n    print(\"  Created proxy (resource not loaded yet)\")\n    print(f\"  {proxy.process()}\")  # Loads on first use\n    print(f\"  {proxy.process()}\")  # Already loaded\n\n    # Protection proxy\n    resource = ExpensiveResource()\n    admin_proxy = ProtectionProxy(resource, \"admin\")\n    user_proxy = ProtectionProxy(resource, \"user\")\n    print(f\"\\n  Admin: {admin_proxy.process()}\")\n    print(f\"  User: {user_proxy.process()}\")\n\n\nprint(\"Q180: Proxy Pattern\")\ndemo_proxy()\nprint()",
