     "code": "import time\n\nclass HeavyResource:\n    def __init__(self, name):\n        self.name = name\n        print(f\"  [Loading {name}... heavy computation]\")\n        time.sleep(0.1)\n    \n    def process(self, data):\n        return f\"Processed '{data}' with {self.name}\"\n\nclass LazyProxy:\n    def __init__(self, name):\n        self.name = name\n        self._resource = None\n    \n    def process(self, data):\n        if self._resource is None:\n            print(f\"  [LazyProxy: First access, loading...]\")\n            self._resource = HeavyResource(self.name)\n        return self._resource.process(data)\n\nclass CachingProxy:\n    def __init__(self, resource):\n        self.resource = resource\n        self.cache = {}\n    \n    def process(self, data):\n        if data not in self.cache:\n            self.cache[data] = self.resource.process(data)\n        else:\n            print(f\"  [Cache hit for '{data}']\")\n        return self.cache[data]\n\n# Lazy loading\nproxy = LazyProxy(\"model\")\nprint(\"Proxy created (not loaded yet)\")\nprint(proxy.process(\"test\"))   # Loads now\nprint(proxy.process(\"test2\"))  # Already loaded\n\n# Caching\nresource = HeavyResource(\"engine\")\ncached = CachingProxy(resource)\nprint(cached.process(\"input1\"))  # Computes\nprint(cached.process(\"input1\"))  # From cache",
